  const savedPlatform=()=>{try{const id=window.localStorage.getItem('dsh-ai-hub:selected-platform');return PLATFORM_NAV.some(p=>p.id===id)?id:'deepseek';}catch{return 'deepseek';}};
  const DASH = '—';
