    if (quota.kind === 'credits') return quota.available === false ? '余额不可用' : `赠送 ${fmtMoney(quota.granted)} · 充值 ${fmtMoney(quota.toppedUp)}`;
    return quota.note ? '无余额接口' : DASH;
