    const usageModelScope = () => view === 'usage' ? usageModel : '';
    const usageScopeKey = () => [view === 'platforms' ? 'platform' : 'global', usagePlatformScope(), usageRange, usageChannel, usageIncludeTests || usageChannel === 'test'].join('|');
    // 平台页与全局页共用一份快照，只渲染与当前筛选一致的数据，避免切换时短暂混入其他平台；
    // 模型搜索只收窄同一范围，等待新快照期间沿用上一份并在前端即时过滤
